                    <div><label for="edit-tailor-quantity-{{ $item->id }}">کتنے سوٹ سلنے ہیں؟</label><input id="edit-tailor-quantity-{{ $item->id }}" class="form-control co-tailoring-quantity" type="number" name="quantity" value="{{ (int)$item->quantity }}" min="1" required></div>
                    <div><label for="edit-tailor-price-{{ $item->id }}">گاہک سے فی سوٹ سلائی رقم</label><input id="edit-tailor-price-{{ $item->id }}" class="form-control co-tailoring-price" type="number" name="unit_price" value="{{ $item->unit_price }}" min="0" step="0.01" required></div>
                    <div class="is-wide co-calculated"><span>کل سلائی رقم</span><strong class="co-tailoring-total" dir="ltr">Rs. {{ number_format((float)$item->line_total,2) }}</strong></div>
                    <div class="is-wide"><label for="edit-due-{{ $item->id }}">مکمل کرنے کی تاریخ</label><input id="edit-due-{{ $item->id }}" class="form-control" type="date" name="due_date" value="{{ $item->due_date?->toDateString() }}" min="{{ now()->toDateString() }}" required></div>
                    <div class="is-wide"><label for="edit-tailor-note-{{ $item->id }}">خصوصی سلائی ہدایات <small class="text-muted">(اختیاری)</small></label><textarea id="edit-tailor-note-{{ $item->id }}" class="form-control" name="note" rows="2">{{ $item->note }}</textarea></div>
