@push('scripts')
<script>
document.addEventListener('DOMContentLoaded',function(){
    var cloth=document.getElementById('co-cloth-select'), color=document.getElementById('co-cloth-color'), price=document.getElementById('co-cloth-price'), length=document.getElementById('co-cloth-length');
    function closeInlineEditors(exceptId){document.querySelectorAll('.co-grid-row.is-new').forEach(function(editor){if(editor.id!==exceptId){editor.hidden=true;var article=editor.closest('[data-order-item]');if(article){var display=article.querySelector('[data-display-row]');if(display)display.hidden=false;}}});document.querySelectorAll('[data-inline-edit]').forEach(function(button){button.setAttribute('aria-expanded',button.dataset.inlineEdit===exceptId?'true':'false')});var add=document.getElementById('co-add-cloth-button');if(add)add.setAttribute('aria-expanded',exceptId==='co-new-cloth-row'?'true':'false');}
    var addButton=document.getElementById('co-add-cloth-button');if(addButton){addButton.addEventListener('click',function(){var row=document.getElementById('co-new-cloth-row');closeInlineEditors(row.id);row.hidden=false;this.setAttribute('aria-expanded','true');var select=row.querySelector('select[name="cloth_id"]');if(select)select.focus();});}
    document.addEventListener('click',function(event){var editButton=event.target.closest('[data-inline-edit]');if(editButton){var editor=document.getElementById(editButton.dataset.inlineEdit);closeInlineEditors(editor.id);var article=editor.closest('[data-order-item]'),display=article&&article.querySelector('[data-display-row]');if(display)display.hidden=true;editor.hidden=false;editButton.setAttribute('aria-expanded','true');var field=editor.querySelector('select,input');if(field)field.focus();return;}var cancelButton=event.target.closest('[data-inline-cancel]');if(cancelButton){closeInlineEditors(null);}});
    if(cloth){var updateClothFields=function(preserveValues){var o=cloth.options[cloth.selectedIndex],form=cloth.closest('.co-cloth-form'),colors=[],unitPrice=Number(o.dataset.price||0),defaultLength=Number(o.dataset.length||4.5),quantity=form.querySelector('.co-cloth-quantity'),suitOnly=form.querySelector('.co-suit-only'),oldColor=preserveValues?(form.dataset.oldColor||''):'';try{colors=JSON.parse(o.dataset.colors||'[]')}catch(e){}color.innerHTML='';if(colors.length){colors.forEach(function(c,index){var x=document.createElement('option');x.value=c;x.textContent=c;x.selected=oldColor?oldColor===c:index===0;color.appendChild(x)});}else{var placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='رنگ لاگو نہیں';color.appendChild(placeholder);}color.required=false;color.disabled=!cloth.value;suitOnly.hidden=o.dataset.basis!=='per_suit';form.dataset.basis=o.dataset.basis||'per_meter';form.dataset.unitPrice=unitPrice;if(!preserveValues){length.value=cloth.value?defaultLength.toFixed(2):'';if(quantity)quantity.value=1;price.value=cloth.value&&unitPrice?(o.dataset.basis==='per_suit'?unitPrice:unitPrice*defaultLength).toFixed(2):'';}};cloth.addEventListener('change',function(){updateClothFields(false);});if(cloth.value)updateClothFields(true);else color.disabled=true;}
    function bindClothForm(form){if(form.dataset.bound==='true')return;form.dataset.bound='true';var quantity=form.querySelector('.co-cloth-quantity'),clothLength=form.querySelector('.co-cloth-length'),total=form.querySelector('.co-cloth-total');function recalculate(){var unit=Number(form.dataset.unitPrice||0);if(!unit||!total)return;total.value=(unit*(form.dataset.basis==='per_suit'?Math.max(1,Number(quantity&&quantity.value||1)):Math.max(0,Number(clothLength&&clothLength.value||0)))).toFixed(2);}if(quantity)quantity.addEventListener('input',recalculate);if(clothLength)clothLength.addEventListener('input',recalculate);}
    document.querySelectorAll('.co-cloth-form').forEach(bindClothForm);
    function money(value){return 'Rs. '+Number(value||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});}
    function updateSummary(summary){document.getElementById('co-summary-subtotal').textContent=money(summary.subtotal);document.getElementById('co-summary-paid').textContent=money(summary.paid);document.getElementById('co-summary-balance').textContent=money(summary.balance);document.getElementById('co-confirmed-count').textContent=summary.confirmed_count;document.getElementById('co-draft-count').textContent=summary.draft_count;document.getElementById('co-draft-total').textContent=money(summary.draft_total);var confirmForm=document.getElementById('co-confirm-form');if(confirmForm){confirmForm.hidden=summary.draft_count<1;var payment=confirmForm.querySelector('[name="payment"]');if(payment)payment.max=summary.draft_total;}}
    function showLiveMessage(message,isError){var alert=document.getElementById('co-live-alert');alert.hidden=false;alert.className='alert co-alert '+(isError?'alert-danger':'alert-success');alert.textContent=message;}
    document.addEventListener('submit',async function(event){var form=event.target.closest('.co-ajax-row-form');if(!form)return;event.preventDefault();var submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{var response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});var data=await response.json();if(!response.ok){var errors=data.errors||{},first=Object.keys(errors).length?errors[Object.keys(errors)[0]][0]:(data.message||'تبدیلی محفوظ نہیں ہوئی۔');showLiveMessage(first,true);return;}var holder=document.createElement('div');holder.innerHTML=data.row_html.trim();var article=holder.firstElementChild,existing=document.querySelector('[data-order-item="'+data.item_id+'"]'),rows=document.getElementById('co-items-rows');if(existing)existing.replaceWith(article);else rows.appendChild(article);var empty=rows.querySelector('.co-empty');if(empty)empty.remove();bindClothForm(article.querySelector('.co-cloth-form'));updateSummary(data.summary);if(form.id==='co-new-cloth-row'){form.reset();color.innerHTML='<option value="">رنگ لاگو نہیں</option>';color.disabled=true;length.value='';price.value='';}closeInlineEditors(null);showLiveMessage(data.message,false);}catch(error){showLiveMessage('تبدیلی محفوظ نہیں ہوئی۔ دوبارہ کوشش کریں۔',true);}finally{if(submit)submit.disabled=false;}});
    document.querySelectorAll('.co-tailoring-form').forEach(function(form){var profile=form.querySelector('.co-profile')||document.getElementById('co-profile'), template=form.querySelector('.co-template')||document.getElementById('co-template'), measurementLink=form.querySelector('.co-measurement-link'), suitQuantity=form.querySelector('.co-tailoring-quantity')||document.getElementById('co-suit-quantity'), tailoringPrice=form.querySelector('.co-tailoring-price')||document.getElementById('co-tailoring-price'), tailoringTotal=form.querySelector('.co-tailoring-total')||document.getElementById('co-tailoring-total');function updateMeasurementLink(){if(!profile||!template||!measurementLink)return;var o=profile.options[profile.selectedIndex], base=o.dataset.measurementUrl||'#';measurementLink.href=base+(base.indexOf('?')===-1?'?':'&')+'measurement_template_id='+encodeURIComponent(template.value);}function updateTailoringTotal(){if(!suitQuantity||!tailoringPrice||!tailoringTotal)return;var total=Math.max(0,Number(suitQuantity.value||0))*Math.max(0,Number(tailoringPrice.value||0));tailoringTotal.textContent='Rs. '+total.toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});}if(profile&&template){profile.addEventListener('change',updateMeasurementLink);template.addEventListener('change',updateMeasurementLink);updateMeasurementLink();}if(suitQuantity&&tailoringPrice){suitQuantity.addEventListener('input',updateTailoringTotal);tailoringPrice.addEventListener('input',updateTailoringTotal);updateTailoringTotal();}});
});
</script>
